      "codigo_refatorado": "using System;\\nusing System.Text;\\nusing UnityEngine;\\n\\nnamespace PerformanceAdvisor.StressTest\\n{\\n    public class StressTestScene : MonoBehaviour\\n    {\\n        public bool stressGc = false;\\n        public bool stressCpu = false;\\n        public bool stressDraw = false;\\n        public GameObject testPrefab;\\n        [Range(1, 20)] public float spawnRadius = 10f;\\n        [Range(1, 50)] public int cubesPerFrame = 1;\\n        public bool useUniqueMaterials = false;\\n        [Range(1, 512)] public int cpuScansPerFrame = 1;\\n        public int emptyObjects = 0;\\n        public int gcConcatIterations = 1000;\\n        public int gcArrayAllocs = 0;\\n        public int overdrawLayers = 0;\\n        public Material overdrawMaterial;\\n        [Range(0, 2000)] public int prepopulateCount = 0;\\n\\n        private StringBuilder _cachedBuilder = new StringBuilder(4096);\\n        private MaterialPropertyBlock _propertyBlock;\\n        private static readonly int ColorPropertyId = Shader.PropertyToID(\"_Color\");\\n\\n        private void Awake()\\n        {\\n            _propertyBlock = new MaterialPropertyBlock();\\n        }\\n\\n        private void Start()\\n        {\\n            if (prepopulateCount > 0 && testPrefab != null)\\n            {\\n                for (int i = 0; i < prepopulateCount; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n\\n            for (int i = 0; i < emptyObjects; i++)\\n            {\\n                new GameObject(\"Empty_\" + i);\\n            }\\n\\n            if (overdrawLayers > 0 && overdrawMaterial != null)\\n            {\\n                BuildOverdrawLayers();\\n            }\\n        }\\n\\n        private void BuildOverdrawLayers()\\n        {\\n            Camera cam = Camera.main;\\n            if (cam == null) return;\\n            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;\\n            for (int i = 0; i < overdrawLayers; i++)\\n            {\\n                float d = cam.nearClipPlane + 0.05f + i * 0.001f;\\n                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;\\n                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);\\n                Destroy(quad.GetComponent<Collider>());\\n                quad.name = \"Overdraw_\" + i;\\n                quad.transform.SetParent(cam.transform, false);\\n                quad.transform.localPosition = new Vector3(0f, 0f, d);\\n                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);\\n                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;\\n            }\\n        }\\n\\n        private void Update()\\n        {\\n            if (stressGc)\\n            {\\n                _cachedBuilder.Clear();\\n                for (int i = 0; i < gcConcatIterations; i++)\\n                {\\n                    _cachedBuilder.Append(i);\\n                }\\n            }\\n\\n            if (stressCpu)\\n            {\\n                // Evita GameObject.FindObjectsOfType no loop de Update\\n            }\\n\\n            if (stressDraw && testPrefab != null)\\n            {\\n                int n = Mathf.Max(1, cubesPerFrame);\\n                for (int i = 0; i < n; i++)\\n                {\\n                    SpawnOne();\\n                }\\n            }\\n        }\\n\\n        private void SpawnOne()\\n        {\\n            var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity);\\n            if (useUniqueMaterials)\\n            {\\n                var renderer = clone.GetComponent<Renderer>();\\n                if (renderer != null)\\n                {\\n                    renderer.GetPropertyBlock(_propertyBlock);\\n                    _propertyBlock.SetColor(ColorPropertyId, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));\\n                    renderer.SetPropertyBlock(_propertyBlock);\\n                }\\n            }\\n        }\\n    }\\n}\",\n      "
          ,"explicacao_didatica": "Em C#, strings são imutáveis: toda vez que você junta um texto com outro usando '+', o Unity cria um novo objeto na memória e descarta o anterior. Fazer isso 1000 vezes todo frame enche a memória rapidamente, obrigando o Garbage Collector a travar o jogo para fazer a limpeza. Usar o StringBuilder reutilizável evita a criação contínua de objetos descartáveis. Além disso, 'renderer.material' duplica materiais na memória a cada acesso, o que foi corrigido utilizando MaterialPropertyBlock para alterar cores sem alocar novos materiais."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Chamada repetitiva a GameObject.FindObjectsOfType<GameObject>() dentro do Update(). Essa função percorre todos os objetos ativos carregados na cena por completo e aloca um array com referências a cada invocação, consumindo tempo excessivo da CPU principal.",
      "codigo_refatorado": "// A busca de objetos em cena foi desativada no Update() do código refatorado. Caso necessite monitorar instâncias, registre os objetos em uma lista estática centralizada no Awake/OnEnable e remova-os no OnDisable/OnDestroy, eliminando varreduras de cena a cada frame.",
      "explicacao_didatica": "Procurar objetos na cena inteira a cada frame é equivalente a procurar uma chave perdida por toda a casa 60 vezes por segundo. O ideal é que cada objeto se apresente e guarde seu contato em uma lista única quando é criado, permitindo acesso instantâneo sem precisar varrer todo o jogo a cada quadro."
    }
